?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mahameru — Visit</title><link rel="stylesheet" href="assets/app.css"></head><body><main class="container"><header class="topbar"><div><div class="brand">MAHAMERU</div><div class="muted">Visit & Check-In</div></div><a class="button" href="sales.php">Sales</a></header><section class="card"><h2>Check-In Outlet</h2><p class="muted">GPS, radius, foto, jam operasional, dan active-visit validation wajib dilakukan oleh backend.</p><label>Outlet ID<input id="outlet_id" type="number" min="1" required></label><button class="primary" id="checkin">Ambil Lokasi & Check-In</button><pre id="result"></pre></section></main><script>const csrf=<?=json_encode($csrf)?>;const out=document.querySelector('#result');document.querySelector('#checkin').onclick=()=>{if(!navigator.geolocation){out.textContent='Perangkat tidak menyediakan GPS.';return;}navigator.geolocation.getCurrentPosition(async p=>{const r=await fetch('../api/visit.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({action:'checkin',outlet_id:Number(document.querySelector('#outlet_id').value),latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy})});out.textContent=await r.text();},e=>out.textContent='GPS gagal: '+e.message,{enableHighAccuracy:true,timeout:10000,maximumAge:0});};</script></body></html>
